export const nyQuestions=rows.map(([topic,page,question,options,explanation,kq,ko,ke],i)=>({id:`ny-q${i+1}`,topic,page,question,options,answer:0,explanation,ka:{question:kq,options:ko,explanation:ke}})).concat(signs.map(([page,question,options,explanation,kq,ko,ke],i)=>({id:`ny-s${i+1}`,image:'./signs/'+['stop.svg','yield.svg','no-uturn.png','workers.png','destination.svg','hospital.png','crossroad.png','speed.svg','advisory.svg','stop.svg'][i],topic:'Signs & signals',roadSign:true,page,question,options,answer:0,explanation,ka:{question:kq,options:ko,explanation:ke}})));
